using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using System.Linq;
public static class BrowserProjectPort {public static void Prepare(){var scene=EditorSceneManager.OpenScene("Assets/MainLevel01.unity");if(!scene.GetRootGameObjects().Any(g=>g.name=="Browser Training Setup")){var setup=new GameObject("Browser Training Setup");setup.AddComponent<BrowserFpsNotice>();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Player.prefab");var positions=new[]{new Vector3(0,2,0),new Vector3(0,2,12),new Vector3(7,2,15),new Vector3(-7,2,15)};for(int i=0;i<positions.Length;i++){var player=(GameObject)PrefabUtility.InstantiatePrefab(prefab);player.name=i==0?"Browser Player":"Browser Target "+i;player.transform.position=positions[i];player.AddComponent<BrowserLocalPlayer>().local=i==0;}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene("Assets/MainLevel01.unity",true)};} }